package br.com.livraria.autor.controller; import br.com.livraria.autor.model.Autor; import br.com.livraria.autor.service.AutorService; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/autor") public class AutorController { private final AutorService service; public AutorController(AutorService service){this.service=service;} @GetMapping public List<Autor> listar(){return service.listar();} @GetMapping("/{id}") public Autor buscar(@PathVariable Long id){return service.buscar(id);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Autor salvar(@RequestBody Autor autor){return service.salvar(autor);} @PutMapping("/{id}") public Autor atualizar(@PathVariable Long id,@RequestBody Autor autor){return service.atualizar(id,autor);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void excluir(@PathVariable Long id){service.excluir(id);} }